 let timer,baseline=snapshot();
 const persist=()=>{try{const current=snapshot();if(current===baseline)localStorage.removeItem(draftKey());else localStorage.setItem(draftKey(),JSON.stringify({time:Date.now(),fields:JSON.parse(current)}))}catch(_){}};
 const schedule=()=>{clearTimeout(timer);timer=setTimeout(persist,250)};
 fields.forEach(el=>{el.addEventListener('input',schedule);el.addEventListener('change',schedule)});
