function esc(x){return String(x??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}
function formatMath(source){let value=String(source??'').trim();for(let i=0;i<6;i++){value=value.replace(/\\(?:d|t)?frac\{([^{}]+)\}\{([^{}]+)\}/g,'($1)/($2)').replace(/\\sqrt(?:\[([^\]]+)\])?\{([^{}]+)\}/g,(_,index,body)=>index?`${index}√(${body})`:`√(${body})`).replace(/\\(?:text|textrm|mathrm|mathit|operatorname)\{([^{}]*)\}/g,'$1').replace(/\\(?:boldsymbol|mathbf)\s*\{([^{}]*)\}/g,'\uE002$1\uE003').replace(/\\(?:overline|underline|vec)\{([^{}]*)\}/g,'$1')}const symbols={'\\neq':'≠','\\ne':'≠','\\geq':'≥','\\ge':'≥','\\leq':'≤','\\le':'≤','\\approx':'≈','\\equiv':'≡','\\times':'×','\\cdot':'·','\\div':'÷','\\pm':'±','\\mp':'∓','\\infty':'∞','\\rightarrow':'→','\\to':'→','\\leftarrow':'←','\\leftrightarrow':'↔','\\Rightarrow':'⇒','\\Leftarrow':'⇐','\\Leftrightarrow':'⇔','\\pi':'π','\\alpha':'α','\\beta':'β','\\gamma':'γ','\\delta':'δ','\\epsilon':'ε','\\theta':'θ','\\lambda':'λ','\\mu':'μ','\\rho':'ρ','\\sigma':'σ','\\phi':'φ','\\omega':'ω','\\Gamma':'Γ','\\Delta':'Δ','\\Theta':'Θ','\\Lambda':'Λ','\\Sigma':'Σ','\\Omega':'Ω','\\sum':'∑','\\prod':'∏','\\int':'∫','\\in':'∈','\\notin':'∉','\\subseteq':'⊆','\\subset':'⊂','\\supseteq':'⊇','\\supset':'⊃','\\cup':'∪','\\cap':'∩','\\emptyset':'∅','\\forall':'∀','\\exists':'∃','\\therefore':'∴','\\because':'∵','\\angle':'∠','\\degree':'°','\\parallel':'∥','\\perp':'⊥','\\triangle':'△','\\circ':'°','\\ldots':'…','\\cdots':'…'};Object.entries(symbols).forEach(([key,symbol])=>{value=value.split(key).join(symbol)});value=value.replace(/\\(?:sin|cos|tan|cot|sec|csc|log|ln|lim|max|min|mod|quad|qquad|displaystyle)(?=[^A-Za-z]|$)/g,match=>match.slice(1)).replace(/\\(?:left|right|,|;|!|\s)/g,'').replace(/\\begin\{(?:aligned|array|cases|matrix|pmatrix|bmatrix|vmatrix|Vmatrix)\}|\\end\{(?:aligned|array|cases|matrix|pmatrix|bmatrix|vmatrix)\}/g,'').replace(/\\\\/g,'  ').replace(/&/g,' ');return esc(value).replace(/\uE002([\s\S]*?)\uE003/g,'<strong>$1</strong>').replace(/\^\{([^{}]+)\}/g,'<sup>$1</sup>').replace(/\^([A-Za-z0-9πθφ∞])/g,'<sup>$1</sup>').replace(/_\{([^{}]+)\}/g,'<sub>$1</sub>').replace(/_([A-Za-z0-9πθφ∞])/g,'<sub>$1</sub>')}
function renderAiText(source){const tokens=[];const hold=html=>{const token=`\uE000${tokens.length}\uE001`;tokens.push(html);return token};let text=String(source??'').replace(/```(?:[A-Za-z0-9_-]+)?\s*([\s\S]*?)```/g,(_,code)=>hold(`<pre><code>${esc(code.trim())}</code></pre>`)).replace(/\$\$([\s\S]*?)\$\$|\\\[([\s\S]*?)\\\]/g,(_,a,b)=>hold(`<div class="math-block">${formatMath(a??b)}</div>`)).replace(/\$([^$\n]+)\$|\\\(([^\n]+?)\\\)/g,(_,a,b)=>hold(`<span class="math-inline">${formatMath(a??b)}</span>`)).replace(/`([^`\n]+)`/g,(_,code)=>hold(`<code>${esc(code)}</code>`)).replace(/\\(?:boldsymbol|mathbf)\s*\{([^{}]*)\}/g,(_,formula)=>hold(`<span class="math-inline">${formatMath(`\\boldsymbol{${formula}}`)}</span>`));let html=esc(text).replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>');html=html.split('\n').map(line=>{if(/^###\s+/.test(line))return `<h4>${line.replace(/^###\s+/,'')}</h4>`;if(/^##\s+/.test(line))return `<h3>${line.replace(/^##\s+/,'')}</h3>`;if(/^#\s+/.test(line))return `<h3>${line.replace(/^#\s+/,'')}</h3>`;if(/^[-*]\s+/.test(line))return `<div class="ai-list-item">• ${line.replace(/^[-*]\s+/,'')}</div>`;if(/^\d+\.\s+/.test(line))return `<div class="ai-list-item">${line}</div>`;if(/^---+$/.test(line.trim()))return '<hr>';return line?`${line}<br>`:'<br>'}).join('');tokens.forEach((value,index)=>{html=html.split(`\uE000${index}\uE001`).join(value)});return html}
function safeCalculate(source){const text=String(source).replace(/\s+/g,'');let at=0;const number=()=>{const start=at;while(/[0-9.]/.test(text[at]||''))at++;if(start===at)throw new Error('需要数字');const value=Number(text.slice(start,at));if(!Number.isFinite(value))throw new Error('数字无效');return value};const primary=()=>{if(text[at]==='('){at++;const value=expression();if(text[at]!==')')throw new Error('括号不匹配');at++;return value}if(text[at]==='√'){at++;const value=primary();if(value<0)throw new Error('实数范围内不能对负数开平方');return Math.sqrt(value)}if(text[at]==='π'){at++;return Math.PI}return number()};const factor=()=>{if(text[at]==='-'){at++;return -factor()}let value=primary();if(text[at]==='^'){at++;value**=factor()}if(text[at]==='%'){at++;value/=100}return value};const term=()=>{let value=factor();while(text[at]==='*'||text[at]==='/'){const op=text[at++],right=factor();if(op==='/'&&right===0)throw new Error('不能除以0');value=op==='*'?value*right:value/right}return value};const expression=()=>{let value=term();while(text[at]==='+'||text[at]==='-'){const op=text[at++],right=term();value=op==='+'?value+right:value-right}return value};const result=expression();if(at!==text.length||!Number.isFinite(result))throw new Error('表达式无效');return result}
