function materialType(material){const name=String(material?.name||'材料'),extension=(name.match(/\.([^.]+)$/)?.[1]||'文件').toLowerCase(),types={pdf:['PDF','pdf'],doc:['DOC','doc'],docx:['DOCX','doc'],xls:['XLS','sheet'],xlsx:['XLSX','sheet'],ppt:['PPT','slide'],pptx:['PPTX','slide'],csv:['CSV','sheet'],txt:['TXT','text'],md:['MD','text'],png:['PNG','image'],jpg:['JPG','image'],jpeg:['JPG','image'],webp:['WEBP','image'],zip:['ZIP','archive'],rar:['RAR','archive']};return types[extension]||[extension.slice(0,4).toUpperCase(),'file']}
