 document.querySelector('#saveMembers')?.addEventListener('click',async event=>{const button=event.currentTarget;button.disabled=true;try{await mutateState('/api/group/members',{method:'POST',body:JSON.stringify({action:'save',members:members()})});toast('成员与角色已保存，请核对后锁定');renderStage1Roles()}catch(e){toast(e.message);button.disabled=false}});
