function renderEvidence(){const s=load();setRoot(shell('student','s4',head('过程证据包','把测量、计算、图像、推理和外部资料与模型版本连接起来。','<a class="btn" href="stage4.html">返回阶段4</a>','阶段4 · 三级页面')+`<div class="grid cols-2"><section class="card"><h2>已有证据</h2>${s.evidence.map((e,i)=>`<div class="evidence-item"><span>${badge(e.type,e.verified?'ok':'warn')}</span><div><b>${esc(e.text)}</b><div class="muted small">来源：${esc(e.source)}</div>${e.file?`<a class="evidence-file" href="/api/files/${encodeURIComponent(e.file.id)}" target="_blank" rel="noopener">📎 ${esc(e.file.name)}（查看附件）</a>`:``}</div><div class="evidence-actions"><button class="btn sm" data-verify="${i}">${e.verified?'已核验':'标为已核验'}</button>${e.file?`<button class="btn sm danger" data-delete-evidence="${i}">删除附件</button>`:``}</div></div>`).join('')}<div class="toolbar">${btn('新增证据','primary','addEvidence')}</div></section><section class="card"><h2>证据链检查</h2><div class="mini-stat"><span>已核验</span><b>${s.evidence.filter(e=>e.verified).length}</b></div><div class="mini-stat"><span>待核验</span><b>${s.evidence.filter(e=>!e.verified).length}</b></div><div class="mini-stat"><span>关联模型版本</span><b>${s.versions.at(-1)?.v||'尚未保存'}</b></div><div class="divider"></div></section></div>`));document.querySelectorAll('[data-verify]').forEach(b=>b.onclick=async()=>{const x=deepClone(load());x.evidence[+b.dataset.verify].verified=true;event(x,'evidence_verify',x.evidence[+b.dataset.verify].text);if(!await save(x))return;toast('已完成一次证据核验');renderEvidence()});document.querySelectorAll('[data-delete-evidence]').forEach(b=>b.onclick=async()=>{if(!confirm('删除这个证据附件吗？'))return;const x=deepClone(load()),item=x.evidence[+b.dataset.deleteEvidence];try{if(item.file?.id){await api('/api/files/'+encodeURIComponent(item.file.id),{method:'DELETE'});await refreshState()}else{x.evidence.splice(+b.dataset.deleteEvidence,1);if(!await save(x))return}toast('证据附件已删除');renderEvidence()}catch(error){toast(error.message)}});document.querySelector('#addEvidence').onclick=()=>{_evidenceFiles=[];modal('新增证据',`<div class="field"><label>证据内容（可选）</label><textarea id="newEvidence" placeholder="可补充说明；公式和过程建议直接上传照片或文件"></textarea></div><div class="field mt8"><label>拍照或上传证据</label><div class="evidence-upload-row"><label class="btn primary evidence-file-button">拍照上传<input id="newEvidencePhoto" type="file" accept="image/*" capture="environment" multiple hidden></label><label class="btn evidence-file-button">选择文件<input id="newEvidenceFile" type="file" accept=".pdf,.docx,.txt,.md,.csv,.png,.jpg,.jpeg,.webp" multiple hidden></label></div><small class="muted">照片会先压缩再上传；可连续拍照或一次选择多张，最多10个附件。</small><div id="evidenceFileName" class="muted small mt8">尚未选择附件</div></div><div class="field mt8"><label>来源</label><select id="newSource"><option>小组计算</option><option>图像核验</option><option>任务材料</option><option>实测数据</option></select></div><div class="toolbar"><button class="btn primary" id="commitEvidence">加入证据包</button></div>`)} }
