 if(locked){document.querySelectorAll('[data-rehearsal-role],#issueProblem,#issueSolution').forEach(el=>el.readOnly=true);document.querySelectorAll('[data-rehearsal-check],#addRehearsalIssue,#saveRehearsal,[data-delete-rehearsal-issue]').forEach(el=>el.disabled=true);return}
