function renderHelp(){
 const s=load(),h=hintStatus(s),params=new URLSearchParams(location.search),allThreads=Array.isArray(s.helpThreads)?s.helpThreads:[],requestedId=params.get('thread'),newConversation=params.has('new');
 const thread=newConversation?null:(allThreads.find(item=>item?.id===requestedId)||h.thread||allThreads.at(-1)||null),isTeacher=thread?.status==='teacher',messages=Array.isArray(thread?.messages)?thread.messages:[],levelNo=Math.max(1,Math.min(3,Number(thread?.currentLevel)||1));let selectedLevel=levelNo;
 const levels=[['L1','轻提示','定位目标与条件'],['L2','结构提示','拆解问题与表征'],['L3','局部提示','示范一步并核验'],['L4','教师介入','转交教师判断']];
 const levelName=number=>studentHintLevelName(`L${number}`);
 const recent=allThreads.slice().reverse().slice(0,12),recentPanel=`<aside class="card help-recent"><div class="help-recent-head"><h2>最近</h2>${newConversationLink('help.html?new=1')}</div>${recent.length?recent.map(item=>`<a class="help-recent-item ${item.id===thread?.id?'current':''}" href="help.html?thread=${encodeURIComponent(item.id)}"><b>${esc(item.type||'未分类')}</b><span>${esc(item.issue||'未命名问题')}</span><small>${item.status==='resolved'?(item.teacherFeedback?'教师已处理':'已解决'):item.status==='teacher'?'等待教师处理':`${item.messages?.length||0}次提示`}</small></a>`).join(''):'<div class="empty">还没有历史求助主题</div>'}</aside>`;
 const quotaBar=`<div class="help-levels">${levels.map(([level,name,desc])=>{const number=Number(level.slice(1)),locked=number>levelNo;return `<button type="button" class="help-level ${level===`L${selectedLevel}`?'current':''} ${number<levelNo?'done':''}" data-help-level="${number}" ${locked||isTeacher?'disabled':''}><span><b>${name}</b><small>${desc}</small></span><strong>${h.u[level]}/${h.p[level]}</strong></button>`}).join('')}</div>`;
 const topic='';
 const formTitle=thread?(thread.status==='resolved'?'恢复这个问题并继续询问':'继续这个问题'):'建立一个求助主题';
 const questionLabel=thread?'这一次还想追问什么（可留空，沿用当前主题）':'用一句话描述具体卡点';
 const questionPlaceholder=thread?'不必重新描述主题，可写这次想核对的具体方面':'例如：不知道怎样把小路宽度写进面积关系';
 const conversation=(messages.length?messages.map(item=>`<div class="help-message"><div class="status-row"><b>${levelName(Number(String(item.level||'L1').slice(1)))}</b>${badge(item.type||thread.type,'blue')}<span class="muted small">${item.time||''}</span></div><div class="small mt8"><b>本组尝试：</b>${esc(item.done||'')}</div><div class="small mt8"><b>本组追问：</b>${esc(item.question||item.prompt||'')}</div><div class="hint-reply ai-message-body mt8">${renderAiText(item.reply||'')}</div>${item.source==='teacher_fallback'?'<div class="action-warning small mt8">教师预设支架 · 本次不扣AI额度</div>':''}</div>`).join(''):'<div class="empty">建立主题并提交第一次问题后，提示链会显示在这里。</div>')+(thread?.teacherFeedback?`<div class="help-message teacher-feedback"><div class="status-row"><b>教师已处理</b>${badge('处理反馈','ok')}</div><div class="hint-reply mt8">${esc(thread.teacherFeedback)}</div></div>`:'');
 const nextLevel=`L${levelNo+1}`,canAdvance=thread&&messages.length&&levelNo<3&&!isTeacher,nextLevelRemaining=Math.max(0,(h.p[nextLevel]||0)-(h.u[nextLevel]||0));
 setRoot(shell('student','help',head('提示与求助','每个问题单独保留对话。完成当前提示后写下新尝试，再进入下一层。',`<a class="btn" href="workspace.html">查看共享工作区</a>`,'分层学习支架')+quotaBar+`<div class="help-layout mt16">${recentPanel}<section class="card"><h2>${formTitle}</h2>${topic}<div class="field mt12"><label>${thread?'根据上一条提示，我们又尝试了什么':'我们已经完成什么'}</label><textarea id="helpDone" placeholder="写出推理、计算、图示或核验结果"></textarea></div><div class="field mt8"><label>本轮卡点类型（可修改）</label><select id="helpType">${['任务理解','变量关系','数学建模','证明推理','数据处理','计算核验','表达与解释'].map(x=>`<option ${thread?.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field mt8"><label>${questionLabel}</label><textarea id="helpIssue" placeholder="${questionPlaceholder}"></textarea></div><div class="checkbox-row mt12"><label><input type="checkbox" id="checkedWork"> 已检查共享工作区</label></div><div class="help-actions"><button class="btn primary" id="requestHint" ${!s.aiOpen||isTeacher||h.u[`L${selectedLevel}`]>=h.p[`L${selectedLevel}`]?'disabled':''}>${s.aiOpen?`继续使用${levelName(selectedLevel)}`:'AI已暂停'}</button>${canAdvance?'<button class="btn" id="advanceHint" '+(!s.aiOpen||nextLevelRemaining<1?'disabled':'')+'>尝试后进入'+levelName(levelNo+1)+'</button>':''}${thread?'<button class="btn ghost" id="resolveHelp">问题已解决 / 关闭主题</button>':''}<button class="btn warn" id="askTeacher" ${h.u.L4>=h.p.L4||isTeacher?'disabled':''}>${isTeacher?'等待教师处理':'请教师介入'}</button></div></section><section class="card"><h2>${thread?'当前主题的提示链':'提示链'}</h2><div class="help-conversation">${conversation}</div></section></div>`));
 const ask=document.querySelector('#requestHint');
 const advance=document.querySelector('#advanceHint');
 document.querySelectorAll('[data-help-level]').forEach(button=>button.onclick=async()=>{selectedLevel=Number(button.dataset.helpLevel);document.querySelectorAll('[data-help-level]').forEach(item=>item.classList.toggle('current',Number(item.dataset.helpLevel)===selectedLevel));if(ask){ask.disabled=!s.aiOpen||isTeacher||h.u[`L${selectedLevel}`]>=h.p[`L${selectedLevel}`];ask.textContent=s.aiOpen?`继续使用${levelName(selectedLevel)}`:'AI已暂停'}if(advance){advance.disabled=!s.aiOpen||nextLevelRemaining<1||selectedLevel!==levelNo;advance.textContent=selectedLevel===levelNo?`尝试后进入${levelName(levelNo+1)}`:`先返回${levelName(levelNo)}`}});
 if(ask)ask.onclick=async()=>{const done=document.querySelector('#helpDone').value.trim(),issue=document.querySelector('#helpIssue').value.trim(),type=document.querySelector('#helpType').value;if(!done||(!issue&&!thread)){toast(thread?'请写出本组的新尝试':'请写出本组的新尝试和一个具体问题');return}ask.disabled=true;ask.textContent='正在生成提示…';try{const result=await api('/api/hints',{method:'POST',body:JSON.stringify({action:'ask',threadId:thread?.id,newThread:newConversation,level:selectedLevel,done,issue,type,checkedWork:document.querySelector('#checkedWork').checked})});toast(result.source==='deepseek'?`${levelName(Number(result.level.slice(1)))}已返回`:'已返回教师预设提示，本次不扣AI额度');await refreshState();history.replaceState(null,'',`help.html?thread=${encodeURIComponent(result.threadId)}`);renderHelp()}catch(e){toast(e.message);ask.disabled=false;ask.textContent=`继续使用${levelName(selectedLevel)}`}};
 advance?.addEventListener('click',async event=>{const advanceButton=event.currentTarget,done=document.querySelector('#helpDone').value.trim(),issue=document.querySelector('#helpIssue').value.trim(),type=document.querySelector('#helpType').value;if(!done){toast(`请先填写看完${levelName(levelNo)}后的新尝试`);document.querySelector('#helpDone').focus();return}advanceButton.disabled=true;advanceButton.textContent=`正在根据新尝试生成${levelName(levelNo+1)}…`;try{const result=await api('/api/hints',{method:'POST',body:JSON.stringify({action:'advance',threadId:thread.id,done,issue,type,checkedWork:document.querySelector('#checkedWork').checked})});toast(`本轮新尝试已用于${studentHintLevelName(result.level)}`);await refreshState();renderHelp()}catch(e){toast(e.message);advanceButton.disabled=false;advanceButton.textContent=`尝试后进入${levelName(levelNo+1)}`}});
 document.querySelector('#resolveHelp')?.addEventListener('click',async()=>{try{await api('/api/hints',{method:'POST',body:JSON.stringify({action:'resolve',threadId:thread.id})});toast('当前问题已关闭，可在“最近”中继续');await refreshState();renderHelp()}catch(e){toast(e.message)}});
 document.querySelector('#askTeacher')?.addEventListener('click',async()=>{const issue=document.querySelector('#helpIssue').value.trim()||thread?.issue||'需要教师介入',type=document.querySelector('#helpType').value;try{const result=await api('/api/hints',{method:'POST',body:JSON.stringify({action:'teacher',threadId:thread?.id,newThread:newConversation,issue,type})});toast(result.message);await refreshState();history.replaceState(null,'',`help.html?thread=${encodeURIComponent(result.threadId)}`);renderHelp()}catch(e){toast(e.message)}});
}
