function teacherMetrics(){const s=load(),total=s.groups.reduce((a,g)=>a+(Number(g.help)||0),0),average=s.groups.length?(total/s.groups.length).toFixed(1):'0.0';return `<div class="grid cols-4">${metric('当前阶段',`${s.currentStage}/5`,stage(s.currentStage).full)}${metric('需要教师',s.queue.filter(q=>!q.resolved).length+'组',s.queue.filter(q=>!q.resolved).map(q=>q.group+'组').join('、')||'当前没有')}${metric('共性卡点',s.common.length+'项',s.common[0]?.title||'尚未形成')}${metric('AI助用',total,`平均 ${average}次/组`)}</div>`}
