let broadcastSyncBusy=false;
async function syncBroadcast(){
 const teacherPage=_session?.role==='teacher'&&document.querySelector('#broadcastReceipts');
 if(document.hidden||(_session?.role!=='student'&&!teacherPage)||broadcastSyncBusy)return;
 broadcastSyncBusy=true;
 try{
  const message=await api('/api/broadcast');
  Object.assign(load(),message);
  if(_session.role==='student')updateBroadcastBanner(message);else updateBroadcastReceipts(message);
 }catch(_){/* Keep the last received announcement and retry on the next poll. */}
 finally{broadcastSyncBusy=false}
}
