function renderBroadcast(){
 const s=load();
 setRoot(shell('teacher','broadcast',head('平台消息广播','向全班小组发布统一答疑、阶段提醒和成果要求。','','教师主动调控')+`<div class="grid cols-2"><section class="card"><div class="field"><label>发送对象</label><input value="全班${s.groupCount}组" readonly></div><div class="field mt8"><label for="bcType">提示类型</label><select id="bcType">${['统一答疑','阶段提醒','时间提醒','成果要求'].map(type=>`<option ${s.broadcastType===type?'selected':''}>${type}</option>`).join('')}</select></div><div class="field mt8"><label for="bcText">广播内容</label><textarea id="bcText" maxlength="2000">${esc(s.broadcast)}</textarea></div><div class="toolbar">${btn('发送广播','primary','sendBc')} ${btn('撤下广播','ghost','clearBc')}</div><p>发送成功代表服务器已保存，不代表所有小组已阅读。</p></section><section class="card"><h2>当前广播与查看状态</h2><div id="bcPublished">${s.broadcast?broadcastBanner(s,'bcPreview'):'<p>暂无广播</p>'}</div><div id="broadcastReceipts" class="mt16">${s.broadcast?broadcastReceipts(s):'<p>暂无广播</p>'}</div></section></div><div class="page-head mt16"><div><h2>共性问题</h2><p>按求助主题聚合多个小组的相同卡点，可直接进入小组记录核对。</p></div></div>`+commonIssues(s)));
 const publish=async clear=>{
  const content=clear?'':document.querySelector('#bcText').value.trim();
  if(!clear&&!content){toast('请填写广播内容');return}
  const buttons=[document.querySelector('#sendBc'),document.querySelector('#clearBc')];
  buttons.forEach(button=>button.disabled=true);
  try{
   const message=await api('/api/broadcast',{method:'POST',body:JSON.stringify({broadcast:content,broadcastType:document.querySelector('#bcType').value})});
   Object.assign(load(),message);
   document.querySelector('#bcPublished').innerHTML=message.broadcast?broadcastBanner(message,'bcPreview'):'<p>暂无广播</p>';updateBroadcastReceipts(message);
   if(clear)document.querySelector('#bcText').value='';
   toast(clear?'广播已撤下':'广播已发布，小组端将自动同步');
  }catch(e){toast('广播操作失败：'+e.message)}
  finally{buttons.forEach(button=>button.disabled=false)}
 };
 document.querySelector('#sendBc').onclick=()=>publish(false);
 document.querySelector('#clearBc').onclick=()=>publish(true);
}
