let desmosLoader;
const DESMOS_TOOLS={graph:{label:'图形计算器',feature:'GraphingCalculator',constructors:['GraphingCalculator','Calculator'],description:'绘制函数、方程、数据表和动态参数。'},scientific:{label:'科学计算器',feature:'ScientificCalculator',constructors:['ScientificCalculator'],description:'完成分数、根式、幂、三角函数和统计计算。'},four:{label:'四功能计算器',feature:'FourFunctionCalculator',constructors:['FourFunctionCalculator'],description:'进行基础运算、分数、百分数和平方根计算。'},geometry:{label:'几何工具',feature:'GeometryCalculator',constructors:['Geometry'],description:'构造并操作点、线、圆、多边形和角。'},threeD:{label:'3D计算器',feature:'Calculator3D',constructors:['Calculator3D'],description:'建立并旋转观察三维曲面、空间曲线和点。'}};
function desmosConstructor(api,tool='graph'){return DESMOS_TOOLS[tool]?.constructors.map(name=>api?.[name]).find(value=>typeof value==='function')||null}
async function loadDesmos(){
 if(desmosConstructor(window.Desmos))return window.Desmos;
 if(desmosLoader)return desmosLoader;
 desmosLoader=(async()=>{const config=await api('/api/math-tools/config');if(!config.apiKey)throw new Error('尚未配置 Desmos API Key');if(window.Desmos&&!desmosConstructor(window.Desmos))delete window.Desmos;return new Promise((resolve,reject)=>{const script=document.createElement('script'),url=new URL('https://www.desmos.com/api/v1.12/calculator.js');url.searchParams.set('apiKey',config.apiKey);url.searchParams.set('lang','zh-CN');script.src=url.toString();const timeout=setTimeout(()=>{script.remove();reject(new Error('连接 Desmos 超时，请检查网络或域名授权'))},15000);script.onload=()=>{clearTimeout(timeout);desmosConstructor(window.Desmos)?resolve(window.Desmos):reject(new Error('Desmos SDK 未完整初始化，请刷新页面后重试'))};script.onerror=()=>{clearTimeout(timeout);reject(new Error('Desmos SDK 加载失败，请检查网络或域名授权'))};document.head.appendChild(script)})})();
 try{return await desmosLoader}catch(error){desmosLoader=null;throw error}
}
async function uploadEvidenceFiles(files,onProgress=()=>{}){
 const results=Array(files.length),workers=Math.min(2,files.length);let cursor=0,completed=0;
 const worker=async()=>{while(cursor<files.length){const index=cursor++;onProgress(`正在压缩 ${index+1}/${files.length}`);await new Promise(requestAnimationFrame);const file=await compressEvidenceImage(files[index]);if(file.size>10*1024*1024)throw new Error('压缩后的文件仍超过10MB：'+file.name);onProgress(`正在上传 ${completed+1}/${files.length}`);const uploaded=await api('/api/files',{method:'POST',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name)},body:file});results[index]={id:uploaded.file.id,name:uploaded.file.name,mime:file.type||'application/octet-stream',size:uploaded.file.size};completed++;onProgress(`已上传 ${completed}/${files.length}`)}};
 try{await Promise.all(Array.from({length:workers},worker));return results}catch(error){error.uploaded=results.filter(Boolean);throw error}
}
function showDesmosError(container,error){const status=container.closest('.desmos-host')?.querySelector('.desmos-status');if(!status)return;status.hidden=false;status.classList.add('error');status.innerHTML=`<b>Desmos 暂时不可用</b><span>${esc(error.message)}</span><span>请确认 API Key 已启用 Graphing Calculator，并允许当前部署域名。</span><a href="https://www.desmos.com/my-api" target="_blank" rel="noopener">检查 Desmos API 设置</a>`}
async function mountDesmos(container,state,tool='graph'){
 const status=container.closest('.desmos-host')?.querySelector('.desmos-status');
 try{const definition=DESMOS_TOOLS[tool],Desmos=await loadDesmos();if(!definition)throw new Error('未知的 Desmos 工具');if(Desmos.enabledFeatures?.[definition.feature]===false)throw new Error(`当前 API Key 未启用 Desmos ${definition.label}`);const createCalculator=desmosConstructor(Desmos,tool);if(!createCalculator)throw new Error(`Desmos SDK 未提供${definition.label}功能`);const options=tool==='four'?{additionalFunctions:['fraction','sqrt']}:tool==='scientific'?{degreeMode:true}:{expressions:true,expressionsTopbar:true,settingsMenu:true,zoomButtons:true,keypad:true,showResetButtonOnGraphpaper:true};const calculator=createCalculator(container,options);calculator.updateSettings?.({language:'zh-CN'});if(state)calculator.setState(state);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(!container.firstElementChild){calculator.destroy();throw new Error('Desmos 组件未完成渲染，请检查 API Key 的域名授权')}status?.remove();container.dataset.desmosReady='true';container.dataset.desmosTool=tool;window.addEventListener('pagehide',()=>calculator.destroy(),{once:true});return calculator}catch(error){showDesmosError(container,error);throw error}
}
function desmosContainer(){return '<div class="desmos-host"><div id="desmosCalculator" class="desmos-calculator" aria-label="中文版 Desmos 数学工具"></div><div class="desmos-status" role="status"><b>正在加载中文版 Desmos…</b><span>首次打开需要连接 Desmos 官方服务。</span></div></div>'}
function resetDesmosContainer(host,label){host.innerHTML=`<div id="desmosCalculator" class="desmos-calculator" aria-label="中文版 Desmos ${esc(label)}"></div><div class="desmos-status" role="status"><b>正在加载${esc(label)}…</b><span>首次打开需要连接 Desmos 官方服务。</span></div>`;return host.querySelector('#desmosCalculator')}
function desmosSwitcherMarkup(active='graph'){return `<div class="desmos-tool-switch" role="tablist" aria-label="选择数学工具">${Object.entries(DESMOS_TOOLS).map(([key,tool])=>`<button class="desmos-tool-tab${key===active?' active':''}" type="button" role="tab" aria-selected="${key===active}" data-desmos-tool="${key}">${tool.label}</button>`).join('')}</div><p class="desmos-tool-description" id="desmosToolDescription">${DESMOS_TOOLS[active].description}</p>${desmosContainer()}`}
async function createDesmosSwitcher(saved={}){
 const host=document.querySelector('.desmos-host'),states={...(saved.states||{})};if(saved.desmosState&&!states.graph)states.graph=saved.desmosState;
 let calculator=null,current=DESMOS_TOOLS[saved.activeTool]?saved.activeTool:'graph',requestId=0;
 const remember=()=>{if(calculator?.getState)states[current]=calculator.getState()};
 const open=async tool=>{if(!DESMOS_TOOLS[tool]||(tool===current&&calculator))return;remember();const id=++requestId;calculator?.destroy();calculator=null;current=tool;document.querySelectorAll('[data-desmos-tool]').forEach(button=>{const active=button.dataset.desmosTool===tool;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});document.querySelector('#desmosToolDescription').textContent=DESMOS_TOOLS[tool].description;try{const instance=await mountDesmos(resetDesmosContainer(host,DESMOS_TOOLS[tool].label),states[tool]||null,tool);if(id!==requestId){instance.destroy();return}calculator=instance}catch(_){}};
 document.querySelectorAll('[data-desmos-tool]').forEach(button=>button.onclick=()=>open(button.dataset.desmosTool));const initial=current;current='';await open(initial);
 return {open,remember,get tool(){return current},get calculator(){return calculator},get container(){return host.querySelector('#desmosCalculator')},states:()=>{remember();return deepClone(states)}};
}
function canvasSnapshot(container,tool){return new Promise((resolve,reject)=>{try{const bounds=container.getBoundingClientRect(),width=Math.max(640,Math.round(bounds.width)),height=Math.max(420,Math.round(bounds.height)),clone=container.cloneNode(true),styles=[...document.querySelectorAll('style')].map(node=>node.textContent).join('\n'),svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml" style="width:${width}px;height:${height}px;background:white;overflow:hidden"><style>${styles.replaceAll('</style>','')}</style>${new XMLSerializer().serializeToString(clone)}</div></foreignObject></svg>`,url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'})),image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,width,height);context.drawImage(image,0,0);URL.revokeObjectURL(url);canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('截图生成失败')),'image/png',.92)};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error(`${DESMOS_TOOLS[tool].label}截图生成失败`))};image.src=url}catch(error){reject(error)}})}
function dataUrlBlob(data){const [header,payload]=String(data).split(','),match=header.match(/^data:([^;]+);base64$/);if(!match||!payload)throw new Error('Desmos 返回的截图格式无效');const binary=atob(payload),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type:match[1]})}
async function captureDesmos(switcher){const calculator=switcher.calculator,container=switcher.container,options={width:Math.min(1600,Math.max(800,Math.round(container.clientWidth))),height:Math.min(1000,Math.max(500,Math.round(container.clientHeight))),targetPixelRatio:1};if(!calculator)throw new Error('数学工具尚未加载完成');if(typeof calculator.asyncScreenshot==='function')return new Promise((resolve,reject)=>calculator.asyncScreenshot(options,data=>{try{resolve(dataUrlBlob(data))}catch(error){reject(error)}}));if(typeof calculator.screenshot==='function'){const data=calculator.screenshot(options);if(data)return dataUrlBlob(data)}return canvasSnapshot(container,switcher.tool)}
async function uploadMathScreenshot(switcher,purpose){const blob=await captureDesmos(switcher),stamp=new Date().toISOString().replace(/[.:]/g,'-'),name=`${purpose==='math-stage'?'阶段3模型检验':'数学工具'}-${DESMOS_TOOLS[switcher.tool].label}-${stamp}.png`,result=await api('/api/files',{method:'POST',headers:{'Content-Type':'image/png','X-File-Name':encodeURIComponent(name),'X-File-Purpose':purpose},body:blob});return {id:result.file.id,name:result.file.name,mime:'image/png',size:result.file.size,tool:switcher.tool,createdAt:result.file.uploadedAt||iso()}}
